class Solution:
    def twoSum(self, nums, target):
        seen = {}
        for i, n in enumerate(nums):
            if target - n in seen: return [seen[target - n], i]
            seen[n] = i
        return []

class Solution:
    def maxArea(self, height: List[int]) -> int:
        left, right = 0, len(height) - 1
        max_water = 0
        while left < right:
            water = (right - left) * min(height[left], height[right])
            max_water = max(max_water, water)
            if height[left] < height[right]: left += 1
            else: right -= 1
        return max_water

class Solution:
    def trap(self, height: List[int]) -> int:
        if not height: return 0
        l, r = 0, len(height) - 1
        l_max, r_max = height[l], height[r]
        water = 0
        while l < r:
            if l_max < r_max:
                l += 1; l_max = max(l_max, height[l]); water += l_max - height[l]
            else:
                r -= 1; r_max = max(r_max, height[r]); water += r_max - height[r]
        return water

class Solution:
    def search(self, nums: List[int], target: int) -> int:
        l, r = 0, len(nums) - 1
        while l <= r:
            mid = (l + r) // 2
            if nums[mid] == target: return mid
            elif nums[mid] < target: l = mid + 1
            else: r = mid - 1
        return -1

class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:
        def findBound(isFirst):
            l, r, bound = 0, len(nums) - 1, -1
            while l <= r:
                mid = (l + r) // 2
                if nums[mid] == target:
                    bound = mid
                    if isFirst: r = mid - 1
                    else: l = mid + 1
                elif nums[mid] < target: l = mid + 1
                else: r = mid - 1
            return bound
        return [findBound(True), findBound(False)]

class Solution:
    def search(self, nums: List[int], target: int) -> int:
        l, r = 0, len(nums) - 1
        while l <= r:
            mid = (l + r) // 2
            if nums[mid] == target: return mid
            if nums[l] <= nums[mid]:
                if nums[l] <= target < nums[mid]: r = mid - 1
                else: l = mid + 1
            else:
                if nums[mid] < target <= nums[r]: l = mid + 1
                else: r = mid - 1
        return -1

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        w_sum = sum(nums[:k])
        max_sum = w_sum
        for i in range(k, len(nums)):
            w_sum += nums[i] - nums[i - k]
            max_sum = max(max_sum, w_sum)
        return max_sum

class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        char_map = {}
        l = 0
        max_len = 0
        for r, char in enumerate(s):
            if char in char_map and char_map[char] >= l:
                l = char_map[char] + 1
            char_map[char] = r
            max_len = max(max_len, r - l + 1)
        return max_len

class Solution:
    def minWindow(self, s: str, t: str) -> str:
        if not t or not s: return ""
        t_count = {}
        for c in t: t_count[c] = t_count.get(c, 0) + 1
        required, formed = len(t_count), 0
        window_count = {}
        l, r = 0, 0
        ans = (float("inf"), None, None)
        while r < len(s):
            c = s[r]
            window_count[c] = window_count.get(c, 0) + 1
            if c in t_count and window_count[c] == t_count[c]: formed += 1
            while l <= r and formed == required:
                c = s[l]
                if r - l + 1 < ans[0]: ans = (r - l + 1, l, r)
                window_count[c] -= 1
                if c in t_count and window_count[c] < t_count[c]: formed -= 1
                l += 1
            r += 1
        return "" if ans[0] == float("inf") else s[ans[1]:ans[2] + 1]

class Solution:
    def groupAnagrams(self, strs: List[str]) -> List[List[str]]:
        mp = collections.defaultdict(list)
        for s in strs:
            key = "".join(sorted(s))
            mp[key].append(s)
        return list(mp.values())

class Solution:
    def subarraySum(self, nums: List[int], k: int) -> int:
        count = 0
        curr_sum = 0
        prefix_map = {0: 1}
        for num in nums:
            curr_sum += num
            if (curr_sum - k) in prefix_map:
                count += prefix_map[curr_sum - k]
            prefix_map[curr_sum] = prefix_map.get(curr_sum, 0) + 1
        return count

class Solution:
    def detectCycle(self, head: Optional[ListNode]) -> Optional[ListNode]:
        slow = fast = head
        while fast and fast.next:
            slow = slow.next; fast = fast.next.next
            if slow == fast:
                slow = head
                while slow != fast:
                    slow = slow.next; fast = fast.next
                return slow
        return None

class Solution:
    def mergeKLists(self, lists: List[Optional[ListNode]]) -> Optional[ListNode]:
        if not lists: return None
        while len(lists) > 1:
            merged = []
            for i in range(0, len(lists), 2):
                l1 = lists[i]
                l2 = lists[i+1] if (i + 1) < len(lists) else None
                merged.append(self.merge2Lists(l1, l2))
            lists = merged
        return lists[0]
    def merge2Lists(self, l1, l2):
        dummy = curr = ListNode()
        while l1 and l2:
            if l1.val < l2.val: curr.next = l1; l1 = l1.next
            else: curr.next = l2; l2 = l2.next
            curr = curr.next
        curr.next = l1 or l2
        return dummy.next

class Solution:
    def invertTree(self, root: Optional[TreeNode]) -> Optional[TreeNode]:
        if not root: return None
        root.left, root.right = self.invertTree(root.right), self.invertTree(root.left)
        return root

class Solution:
    def isValidBST(self, root: Optional[TreeNode]) -> bool:
        def validate(node, low=float('-inf'), high=float('inf')):
            if not node: return True
            if node.val <= low or node.val >= high: return False
            return validate(node.left, low, node.val) and validate(node.right, node.val, high)
        return validate(root)

class Codec:
    def serialize(self, root):
        vals = []
        def dfs(node):
            if not node: vals.append("N"); return
            vals.append(str(node.val)); dfs(node.left); dfs(node.right)
        dfs(root)
        return ",".join(vals)
    def deserialize(self, data):
        vals = iter(data.split(","))
        def dfs():
            val = next(vals)
            if val == "N": return None
            node = TreeNode(int(val)); node.left = dfs(); node.right = dfs()
            return node
        return dfs()

class Solution:
    def climbStairs(self, n: int) -> int:
        if n <= 2: return n
        a, b = 1, 2
        for _ in range(3, n + 1):
            a, b = b, a + b
        return b

class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        dp = [float('inf')] * (amount + 1)
        dp[0] = 0
        for i in range(1, amount + 1):
            for coin in coins:
                if i - coin >= 0:
                    dp[i] = min(dp[i], 1 + dp[i - coin])
        return dp[amount] if dp[amount] != float('inf') else -1

class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        m, n = len(word1), len(word2)
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m + 1): dp[i][0] = i
        for j in range(n + 1): dp[0][j] = j
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if word1[i-1] == word2[j-1]: dp[i][j] = dp[i-1][j-1]
                else: dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
        return dp[m][n]

class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        if not grid: return 0
        R, C = len(grid), len(grid[0])
        count = 0
        def dfs(r, c):
            if r < 0 or r >= R or c < 0 or c >= C or grid[r][c] == '0': return
            grid[r][c] = '0'
            dfs(r+1, c); dfs(r-1, c); dfs(r, c+1); dfs(r, c-1)
        for r in range(R):
            for c in range(C):
                if grid[r][c] == '1':
                    count += 1; dfs(r, c)
        return count

class Solution:
    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:
        adj = collections.defaultdict(list)
        indegree = [0] * numCourses
        for dest, src in prerequisites:
            adj[src].append(dest); indegree[dest] += 1
        q = collections.deque([i for i in range(numCourses) if indegree[i] == 0])
        res = []
        while q:
            node = q.popleft()
            res.append(node)
            for neighbor in adj[node]:
                indegree[neighbor] -= 1
                if indegree[neighbor] == 0: q.append(neighbor)
        return res if len(res) == numCourses else []

class Solution:
    def isValid(self, s: str) -> bool:
        stack = []
        mapping = {")": "(", "}": "{", "]": "["}
        for char in s:
            if char in mapping:
                top = stack.pop() if stack else '#'
                if mapping[char] != top: return False
            else: stack.append(char)
        return not stack

class Solution:
    def dailyTemperatures(self, temperatures: List[int]) -> List[int]:
        res = [0] * len(temperatures)
        stack = [] # (temp, index)
        for i, t in enumerate(temperatures):
            while stack and t > stack[-1][0]:
                _, stack_i = stack.pop()
                res[stack_i] = i - stack_i
            stack.append((t, i))
        return res

class Solution:
    def largestRectangleArea(self, heights: List[int]) -> int:
        max_area = 0
        stack = [] # (index, height)
        for i, h in enumerate(heights):
            start = i
            while stack and stack[-1][1] > h:
                index, height = stack.pop()
                max_area = max(max_area, height * (i - index))
                start = index
            stack.append((start, h))
        for i, h in stack:
            max_area = max(max_area, h * (len(heights) - i))
        return max_area

class Solution:
    def sortColors(self, nums: List[int]) -> None:
        l, mid, r = 0, 0, len(nums) - 1
        while mid <= r:
            if nums[mid] == 0:
                nums[l], nums[mid] = nums[mid], nums[l]
                l += 1; mid += 1
            elif nums[mid] == 1: mid += 1
            else:
                nums[mid], nums[r] = nums[r], nums[mid]
                r -= 1

class Solution:
    def merge(self, intervals: List[List[int]]) -> List[List[int]]:
        intervals.sort(key=lambda x: x[0])
        merged = []
        for interval in intervals:
            if not merged or merged[-1][1] < interval[0]: merged.append(interval)
            else: merged[-1][1] = max(merged[-1][1], interval[1])
        return merged

import heapq
class Solution:
    def findKthLargest(self, nums: List[int], k: int) -> int:
        heap = []
        for num in nums:
            heapq.heappush(heap, num)
            if len(heap) > k: heapq.heappop(heap)
        return heap[0]

