class Solution:
    def solveLevel1(self, nums: List[int], target: int) -> int:
        l, r = 0, len(nums) - 1
        while l <= r:
            mid = (l + r) // 2
            if nums[mid] == target: return mid
            elif nums[mid] < target: l = mid + 1
            else: r = mid - 1
        return -1

class Solution:
    def solveLevel2(self, nums: List[int], target: int) -> List[int]:
        def search(is_left):
            l, r, ans = 0, len(nums) - 1, -1
            while l <= r:
                mid = (l + r) // 2
                if nums[mid] == target:
                    ans = mid
                    if is_left: r = mid - 1
                    else: l = mid + 1
                elif nums[mid] < target: l = mid + 1
                else: r = mid - 1
            return ans
        return [search(True), search(False)]

class Solution:
    def solveLevel3(self, nums: List[int], target: int) -> int:
        l, r = 0, len(nums) - 1
        while l <= r:
            mid = (l + r) // 2
            if nums[mid] == target: return mid
            if nums[l] <= nums[mid]:
                if nums[l] <= target < nums[mid]: r = mid - 1
                else: l = mid + 1
            else:
