class Solution:
    def solveLevel3(self, s: str, t: str) -> str:
        from collections import Counter
        need, missing = Counter(t), len(t)
        l = start = end = 0
        for r, char in enumerate(s, 1):
            missing -= need[char] > 0
            need[char] -= 1
            if not missing:
                while need[s[l]] < 0:
                    need[s[l]] += 1; l += 1
                if not end or r - l < end - start:
                    start, end = l, r
                need[s[l]] += 1; missing += 1; l += 1
        return s[start:end]

