class Solution:
    def solveLevel1(self, n: int, edges: List[List[int]], source: int, destination: int) -> bool:
        from collections import defaultdict, deque
        adj = defaultdict(list)
        for u, v in edges:
            adj[u].append(v); adj[v].append(u)
        q, visited = deque([source]), {source}
        while q:
            curr = q.popleft()
            if curr == destination: return True
            for neighbor in adj[curr]:
                if neighbor not in visited:
                    visited.add(neighbor); q.append(neighbor)
        return False

class Solution:
    def solveLevel2(self, grid: List[List[str]]) -> int:
        if not grid: return 0
        m, n = len(grid), len(grid[0])
        count = 0
        def dfs(r, c):
            if r < 0 or r >= m or c < 0 or c >= n or grid[r][c] == '0': return
            grid[r][c] = '0'
            dfs(r+1, c); dfs(r-1, c); dfs(r, c+1); dfs(r, c-1)
        for i in range(m):
            for j in range(n):
                if grid[i][j] == '1': count += 1; dfs(i, j)
        return count

