class Solution:
    def solveLevel1(self, nums: List[int], k: int) -> int:
        curr = sum(nums[:k])
        max_s = curr
        for i in range(k, len(nums)):
            curr += nums[i] - nums[i - k]
            max_s = max(max_s, curr)
        return max_s

class Solution:
    def solveLevel2(self, s: str) -> int:
        char_set = set()
        l, max_len = 0, 0
        for r in range(len(s)):
            while s[r] in char_set:
                char_set.remove(s[l]); l += 1
            char_set.add(s[r])
            max_len = max(max_len, r - l + 1)
        return max_len

class Solution:
    def solveLevel3(self, s: str, t: str) -> str:
        from collections import Counter
        need, missing = Counter(t), len(t)
        l = start = end = 0
        for r, char in enumerate(s, 1):
            missing -= need[char] > 0
            need[char] -= 1
            if not missing:
                while need[s[l]] < 0:
                    need[s[l]] += 1; l += 1
                if not end or r - l < end - start:
                    start, end = l, r
                need[s[l]] += 1; missing += 1; l += 1
        return s[start:end]

