class Solution:
    def solveLevel1(self, s: str) -> bool:
        stack = []
        mapping = {")": "(", "}": "{", "]": "["}
        for char in s:
            if char in mapping:
                top = stack.pop() if stack else '#'
                if mapping[char] != top: return False
            else: stack.append(char)
        return not stack

class Solution:
    def solveLevel2(self, temperatures: List[int]) -> List[int]:
        ans = [0] * len(temperatures)
        stack = []
        for i, t in enumerate(temperatures):
            while stack and temperatures[stack[-1]] < t:
                prev = stack.pop()
                ans[prev] = i - prev
            stack.append(i)
        return ans

class Solution:
    def solveLevel3(self, heights: List[int]) -> int:
        heights.append(0)
        stack, max_area = [], 0
        for i, h in enumerate(heights):
            while stack and heights[stack[-1]] >= h:
                H = heights[stack.pop()]
                W = i if not stack else i - stack[-1] - 1
                max_area = max(max_area, H * W)
            stack.append(i)
        return max_area

